    arena:['你對著木樁反覆練習，掌心的光一次比一次穩。','你繞著試煉場跑了三圈，再練了一輪基本手勢。','你看高年級生對練，默默記下他們收招的節奏。','你把一道最基礎的術式練了一百遍，終於不再抖了。'],
    herb:['你在藥圃幫忙除草，認識了三種新的靈草。','你蹲在苗床邊，看一株幼苗慢慢轉向陽光。','你替藥圃的花澆了一輪水，袖口都沾上了泥。','你把一株受傷的靈草移到陰涼處，它的葉子好像精神了些。'],
