    lake:['湖面很平靜。你在岸邊坐了一下午，心也跟著靜下來。','你沿著湖岸散步，撿到一片被水磨圓的花石。','你看著水鳥掠過湖面，在水上劃出一道長長的線。','湖心亭裡有人在吹笛。你聽完一整曲，才發現天色暗了。']
