    bo:['你翻完了半本《花靈通論》，在書頁空白處寫滿筆記。','你把這週的課堂筆記重新整理了一遍，順便畫了張圖。','你讀到一段關於玉蘭院的記載，字跡卻在關鍵處模糊了。'],
    qiao:['你縫好一個香囊，拿到市集換了些靈石。','你削了一支木簪，送去市集的飾品攤寄賣。','你用碎布拼了一個小茶墊，攤販一眼就看中了。'],
    gan:['你閉上眼，聽見窗外花靈細微的低語。','你靜坐了一炷香，感覺到整座宿舍的靈息在慢慢呼吸。','冥想中，你好像看見了一片白色的花瓣。睜開眼，什麼都沒有。'],
    feng:['你臨了一整頁的字帖，最後一個字寫得格外好看。','你插了一瓶花放在窗台，室友經過時多看了兩眼。','你學著吹了一段笛子，雖然破了音，自己卻很開心。']
